final class LocalTaskRepository implements TaskRepository { const LocalTaskRepository(this.dao); final TaskDao dao; @override Future<Task?> getTaskById(String id) async=>(await dao.getTaskById(id))?.toDomain(); @override Future<Task?> getTaskByNumber(String id) async=>(await dao.getTaskByNumber(id))?.toDomain(); @override Future<List<Task>> getTasks() async=>(await dao.getTasks()).map((e)=>e.toDomain()).toList(); @override Future<List<Task>> getTasksForUser(String id) async=>(await dao.getTasksForUser(id)).map((e)=>e.toDomain()).toList(); @override Future<List<Task>> getTasksForTeam(String id) async=>(await dao.getTasksForTeam(id)).map((e)=>e.toDomain()).toList(); @override Future<List<Task>> getTasksByBatch(String id) async=>(await dao.getTasksByBatch(id)).map((e)=>e.toDomain()).toList(); @override Future<List<Task>> getSubtasks(String id) async=>(await dao.getSubtasks(id)).map((e)=>e.toDomain()).toList(); @override Future<List<TaskAssignment>> getTaskAssignments(String id) async=>(await dao.getTaskAssignments(id)).map((e)=>e.toDomain()).toList(); @override Future<List<ChecklistItem>> getChecklistItems(String id) async=>(await dao.getChecklistItems(id)).map((e)=>e.toDomain()).toList(); @override Future<List<TaskComment>> getComments(String id) async=>(await dao.getComments(id)).map((e)=>e.toDomain()).toList(); @override Future<List<TaskAttachment>> getAttachments(String id) async=>(await dao.getAttachments(id)).map((e)=>e.toDomain()).toList(); @override Future<List<TaskBlocker>> getBlockers(String id) async=>(await dao.getBlockers(id)).map((e)=>e.toDomain()).toList(); @override Future<List<DeadlineExtensionRequest>> getExtensionRequests(String id) async=>(await dao.getExtensionRequests(id)).map((e)=>e.toDomain()).toList(); @override Future<List<TaskApproval>> getApprovals(String id) async=>(await dao.getApprovals(id)).map((e)=>e.toDomain()).toList(); @override Future<void> insertTaskRecord(Task v)=>dao.insertTask(v.toCompanion()); @override Future<void> updateTaskRecord(Task v) async {await dao.updateTask(v.toCompanion());} @override Future<void> insertAssignments(List<TaskAssignment> v)=>dao.insertAssignments(v.map((e)=>e.toCompanion()).toList()); }
